  ...(faculty('med')?[{l:'의학생으로서 부상자를 돌본다',s:'학식·명성',a:'study pious',f:()=>say('오텔디외로 실려 온 부상자들의 상처를 꿰맸다.'+fx({edu:2,fame:2,soc:2})+addGrade(3))}]:[]),
